mapper.select:
SELECT RATE_RES_CHG_SEQ
FROM (
         SELECT RATE_RES_CHG_SEQ
         FROM NMCP_RATE_RES_CHG_BAS@DL_MCP
         WHERE SVC_CNTR_NO =#{svcCntrNo}
           AND MOBILE_NO =#{mobileNo}
           AND BATCH_RSLT_CD IS NULL
         ORDER BY RES_CHG_APY_DATE DESC
     )
WHERE ROWNUM =1
